664	        if (active) setActive(null);
665	        else if (activeGame) setActiveGame(null);
666	        else setOpen(false);
667	      }
668	    };
669	    window.addEventListener("keydown", onKey);
670	    return () => window.removeEventListener("keydown", onKey);
671	  }, [open, active, activeGame]);
672	
