692	        {!open && unreadCount > 0 && (
693	          <span className="absolute -top-1 -right-1 min-w-5 h-5 px-1.5 rounded-full bg-red-500 text-white text-[11px] font-bold flex items-center justify-center shadow-md ring-2 ring-background">
694	            {unreadCount > 99 ? "99+" : unreadCount}
