699	      {/* Chat panel */}
700	      {open && (
701	        <div
702	          className="fixed z-[59] bg-card border border-border shadow-2xl overflow-hidden flex flex-col
703	            bottom-0 right-0 left-0 top-0 rounded-none
704	            sm:bottom-24 sm:right-6 sm:left-auto sm:top-auto sm:rounded-2xl sm:w-[380px] sm:h-[560px] sm:max-h-[calc(100dvh-8rem)]"
705	          role="dialog"
706	          aria-label="Žinutės"
707	        >
