709	            {active || activeGame ? (
710	              <div className="flex items-center gap-2 min-w-0">
711	                <MessageCircle className="w-4 h-4 text-primary shrink-0"/>
712	                <span className="font-semibold text-sm truncate">Pokalbis</span>
