const SPORT_GENITIVE: Record<string, string> = {
  tennis: "Teniso", basketball: "Krepšinio", padel: "Padelio",
  football: "Futbolo", badminton: "Badmintono", squash: "Skvošo",
  "table-tennis": "Stalo teniso", golf: "Golfo", snooker: "Snukerio",
  bowling: "Boulingo", volleyball: "Tinklinio", hockey: "Ledo ritulio",
  futsal: "Futsalo", floorball: "Florbolо", "beach-volleyball": "Paplūdimio tinklinio",
  pickleball: "Pickleball",
};

function MatchCard({ m, isOwn }: { m: FeedItem; isOwn?: boolean }) {
  const isCasual = m.kind === "casual";
  const isRated = m.matchType === "rated";
  const full = m.slotsLeft === 0;
