  --badge-outline: rgba(0,0,0, .05);

  --opaque-button-border-intensity: -8; 

  --elevate-1: rgba(0,0,0, .03);
  --elevate-2: rgba(0,0,0, .08);

  /* Bold sports theme - vivid primary with stark contrast */
  --background: 210 100% 100%;
  --foreground: 211 60% 18%;

  --card: 205 32% 96%;
  --card-foreground: 211 60% 18%;
  --card-border: 207 27% 91%;

  --popover: 205 32% 96%;
  --popover-foreground: 211 60% 18%;
  --popover-border: 207 27% 91%;

  --primary: 74 73% 56%;
  --primary-foreground: 211 60% 18%;

  --secondary: 210 33% 90%;
  --secondary-foreground: 211 60% 18%;

  --muted: 206 31% 94%;
  --muted-foreground: 209 34% 44%;

  --accent: 206 31% 94%;
  --accent-foreground: 211 60% 18%;

  --destructive: 0 84.2% 60.2%;
  --destructive-foreground: 0 0% 98%;

  --border: 207 27% 91%;
  --input: 207 27% 91%;
  --ring: 74 73% 56%;

  --chart-1: 12 76% 61%;
  --chart-2: 173 58% 39%;
  --chart-3: 197 37% 24%;
  --chart-4: 43 74% 66%;
  --chart-5: 27 87% 67%;

  --app-font-sans: 'Inter', -apple-system, sans-serif;
  --app-font-serif: Georgia, serif;
  --app-font-mono: Menlo, monospace;
  --radius: 0.5rem; 

  --sidebar-primary-border: hsl(from hsl(var(--sidebar-primary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --sidebar-accent-border: hsl(from hsl(var(--sidebar-accent)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --primary-border: hsl(from hsl(var(--primary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --secondary-border: hsl(from hsl(var(--secondary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --muted-border: hsl(from hsl(var(--muted)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --accent-border: hsl(from hsl(var(--accent)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --destructive-border: hsl(from hsl(var(--destructive)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
}

.dark {
  --button-outline: rgba(255,255,255, .10);
  --badge-outline: rgba(255,255,255, .05);

  --opaque-button-border-intensity: 9;

  --elevate-1: rgba(255,255,255, .04);
  --elevate-2: rgba(255,255,255, .09);

  --background: 211 60% 18%;
  --foreground: 0 0% 98%;

  --card: 211 60% 18%;
  --card-foreground: 0 0% 98%;
  --card-border: 240 3.7% 15.9%;

  --popover: 211 60% 18%;
  --popover-foreground: 0 0% 98%;
  --popover-border: 240 3.7% 15.9%;

  --primary: 74 73% 56%;
  --primary-foreground: 211 60% 18%;

  --secondary: 211 37% 24%;
  --secondary-foreground: 0 0% 98%;

  --muted: 211 37% 24%;
  --muted-foreground: 240 5% 64.9%;

  --accent: 211 37% 24%;
  --accent-foreground: 0 0% 98%;

  --destructive: 0 62.8% 30.6%;
  --destructive-foreground: 0 0% 98%;

  --border: 211 37% 24%;
  --input: 211 37% 24%;
  --ring: 74 73% 56%;

  --chart-1: 220 70% 50%;
  --chart-2: 160 60% 45%;
  --chart-3: 30 80% 55%;
  --chart-4: 280 65% 60%;
  --chart-5: 340 75% 55%;
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply font-sans antialiased bg-background text-foreground;
    background-color: var(--bg-color);
    color: var(--text-primary);
  }
  h1, h2, h3 {
    color: var(--text-primary);
  }
  nav a {
    color: var(--text-primary);
  }
}

@layer components {
  .button-primary,
  .cta {
    background-color: var(--brand-action);
    color: var(--text-primary);
    border: 1px solid var(--brand-border);
    box-shadow: 0 10px 24px rgba(197, 224, 65, 0.18);
  }
  .card {
    background-color: var(--bg-card);
    border: 1px solid var(--brand-border);
  }
}

/* Time slider thumb styling */
input[type="range"].time-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #84cc16;
  cursor: pointer;
  border: 2px solid #fff;
  box-shadow: 0 0 0 3px rgba(132,204,22,0.3);
  transition: box-shadow 0.15s;
}
input[type="range"].time-slider::-webkit-slider-thumb:hover {
  box-shadow: 0 0 0 5px rgba(132,204,22,0.4);
}
input[type="range"].time-slider::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #84cc16;
  cursor: pointer;
  border: 2px solid #fff;
  box-shadow: 0 0 0 3px rgba(132,204,22,0.3);
}
input[type="range"].time-slider::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: 3px;
}

