  --border: 211 37% 24%;
  --input: 211 37% 24%;
  --ring: 74 73% 56%;

  --chart-1: 220 70% 50%;
  --chart-2: 160 60% 45%;
  --chart-3: 30 80% 55%;
  --chart-4: 280 65% 60%;
  --chart-5: 340 75% 55%;
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply font-sans antialiased bg-background text-foreground;
    background-color: var(--bg-color);
    color: var(--text-primary);
  }
  nav a {
    color: inherit;
  }
}

@layer components {
  .button-primary,
  .cta {
    background-color: var(--brand-action);
    color: var(--text-primary);
    border: 1px solid var(--brand-border);
    box-shadow: 0 10px 24px rgba(197, 224, 65, 0.18);
  }
