1	/**
2	 * Open Matches routes
3	 *
4	 * GET /api/matches/open — unified feed: split-payment booked matches + casual community games
5	 */
6	import { Router, type IRouter } from "express";
7	import { and, eq, gte, sql, inArray, isNull } from "drizzle-orm";
8	import {
9	  db,
10	  bookingsTable,
11	  courtsTable,
12	  facilitiesTable,
13	  gamesTable,
14	  gameParticipantsTable,
15	  userRatingsTable,
16	} from "@workspace/db";
17	import { logger } from "../lib/logger";
18	
19	const router: IRouter = Router();
20	
21	router.get("/matches/open", async (req, res): Promise<void> => {
22	  try {
23	    const { sport, city, date, skillLevel, limit } = req.query as Record<string, string | undefined>;
24	    const maxRows = Math.min(parseInt(limit ?? "60", 10) || 60, 100);
25	    const userSkill = skillLevel != null && skillLevel !== "" ? parseFloat(skillLevel) : null;
26	
27	    const today = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
28	    const nowIso = new Date().toISOString();
29	
30	    // ── 1. Booked matches (split-payment games linked to a real court booking) ──
31	    const bookedConditions: any[] = [
32	      eq(gamesTable.visibility, "public"),
33	      eq(gamesTable.status, "awaiting_players"),
34	      gte(bookingsTable.date, today),
35	    ];
36	    if (sport && sport !== "all") bookedConditions.push(eq(gamesTable.sport, sport));
37	    if (city) bookedConditions.push(eq(gamesTable.city, city));
38	
39	    const bookedRows = await db
40	      .select({
41	        game: gamesTable,
42	        booking: bookingsTable,
43	        court: courtsTable,
44	        facility: facilitiesTable,
45	      })
46	      .from(gamesTable)
47	      .innerJoin(bookingsTable, eq(gamesTable.bookingId, bookingsTable.id))
48	      .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
49	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
50	      .where(and(...bookedConditions))
51	      .orderBy(bookingsTable.date, bookingsTable.startTime)
52	      .limit(maxRows);
53	
54	    // ── 2. Casual community games (no court booking) ──
55	    // isPrivate is the authoritative privacy field; visibility may be stale on older rows.
56	    const casualConditions: any[] = [
57	      eq(gamesTable.status, "open"),
58	      eq(gamesTable.isPrivate, false),
59	      isNull(gamesTable.bookingId),
60	      gte(gamesTable.datetime, nowIso),
61	    ];
62	    if (sport && sport !== "all") casualConditions.push(eq(gamesTable.sport, sport));
63	    if (city) casualConditions.push(eq(gamesTable.city, city));
64	
65	    const casualRows = await db
66	      .select({ game: gamesTable })
67	      .from(gamesTable)
68	      .where(and(...casualConditions))
69	      .orderBy(gamesTable.datetime)
70	      .limit(maxRows);
71	
72	    // ── 3. Apply date filter ──
73	    let filteredBooked = bookedRows;
74	    let filteredCasual = casualRows;
75	    if (date) {
76	      filteredBooked = bookedRows.filter(r => r.booking.date === date);
77	      filteredCasual = casualRows.filter(r => String(r.game.datetime).startsWith(date));
78	    }
79	
80	    // ── 4. Apply optional skill filter to booked matches ──
81	    if (userSkill != null && !isNaN(userSkill)) {
82	      filteredBooked = filteredBooked.filter(r => {
83	        const min = r.game.minSkillLevel;
84	        const max = r.game.maxSkillLevel;
85	        if (min != null && userSkill < min) return false;
86	        if (max != null && userSkill > max) return false;
87	        return true;
88	      });
89	    }
90	
91	    // ── 5. Fetch creator ELO ratings per sport ──
92	    const creatorSportPairs = [
93	      ...filteredBooked.map(r => ({ userId: r.game.creatorUserId, sport: r.game.sport })),
94	      ...filteredCasual.map(r => ({ userId: r.game.creatorUserId, sport: r.game.sport })),
95	    ];
96	    const uniqueCreatorIds = [...new Set(creatorSportPairs.map(p => p.userId))];
97	    const creatorEloMap = new Map<string, number>(); // key: "userId::sport"
98	    if (uniqueCreatorIds.length > 0) {
99	      const ratingRows = await db
100	        .select({ userId: userRatingsTable.userId, sportSlug: userRatingsTable.sportSlug, elo: userRatingsTable.elo })
101	        .from(userRatingsTable)
102	        .where(inArray(userRatingsTable.userId, uniqueCreatorIds));
103	      for (const r of ratingRows) creatorEloMap.set(`${r.userId}::${r.sportSlug}`, r.elo);
104	    }
105	
106	    // ── 7. Aggregate participant counts for all games ──
107	    const allGameIds = [
108	      ...filteredBooked.map(r => r.game.id),
109	      ...filteredCasual.map(r => r.game.id),
110	    ];
111	    const participantCounts = new Map<number, { paid: number; pending: number; joined: number }>();
112	
113	    if (allGameIds.length > 0) {
114	      const participantRows = await db
115	        .select({
116	          gameId: gameParticipantsTable.gameId,
117	          paymentStatus: gameParticipantsTable.paymentStatus,
118	          count: sql<string>`count(*)`,
119	        })
120	        .from(gameParticipantsTable)

