const MAP_CONTAINER_STYLE = { width: "100%", height: "100%" };
const LIBRARIES: ("places")[] = ["places"];

export const LT_CITY_COORDS: Record<string, [number, number]> = {
  "Vilnius": [54.6872, 25.2797],
