  "Marijampolė": [54.5667, 23.3667],
  "Mažeikiai": [56.3167, 22.3333],
  "Jonava": [55.0833, 24.2833],
  "Utena": [55.5000, 25.6000],
  "Plungė": [55.9167, 21.8500],
  "Kėdainiai": [55.2833, 23.9667],
